CREATE TYPE "OfferStatus" AS ENUM ('open','accepted','withdrawn');
CREATE TYPE "ImportLineState" AS ENUM ('unresolved','resolved','ignored');
CREATE TABLE "Member" ("id" UUID PRIMARY KEY,"name" VARCHAR(40) NOT NULL UNIQUE,"nameKey" VARCHAR(160) NOT NULL UNIQUE,"color" VARCHAR(7) NOT NULL,"revision" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Member_revision_check" CHECK ("revision">=0),CONSTRAINT "Member_color_check" CHECK ("color" ~ '^#[0-9A-Fa-f]{6}$'));
CREATE TABLE "Want" ("id" UUID PRIMARY KEY,"memberId" UUID NOT NULL REFERENCES "Member"("id") ON DELETE CASCADE,"scryfallId" UUID NOT NULL,"cardName" TEXT NOT NULL,"imageUrl" TEXT,"setCode" VARCHAR(16) NOT NULL,"collectorNo" TEXT NOT NULL,"rarity" TEXT NOT NULL,"colors" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],"qty" INTEGER NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "Want_qty_check" CHECK ("qty" BETWEEN 1 AND 9999),UNIQUE("memberId","scryfallId"));
CREATE TABLE "Offer" ("id" UUID PRIMARY KEY,"wantId" UUID NOT NULL REFERENCES "Want"("id") ON DELETE CASCADE,"offererId" UUID NOT NULL REFERENCES "Member"("id") ON DELETE CASCADE,"qty" INTEGER NOT NULL,"unitPriceHkd" DECIMAL(12,2) NOT NULL,"status" "OfferStatus" NOT NULL DEFAULT 'open',"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "Offer_qty_check" CHECK ("qty" BETWEEN 1 AND 9999),CONSTRAINT "Offer_price_check" CHECK ("unitPriceHkd">=0),UNIQUE("wantId","offererId"));
CREATE INDEX "Offer_offererId_idx" ON "Offer"("offererId");
CREATE UNIQUE INDEX "Offer_one_accepted_per_want" ON "Offer"("wantId") WHERE "status"='accepted';
CREATE TABLE "ImportBatch" ("id" UUID PRIMARY KEY,"memberId" UUID NOT NULL REFERENCES "Member"("id") ON DELETE CASCADE,"requestId" UUID NOT NULL,"contentHash" VARCHAR(64) NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("memberId","requestId"));
CREATE TABLE "ImportLine" ("id" UUID PRIMARY KEY,"batchId" UUID NOT NULL REFERENCES "ImportBatch"("id") ON DELETE CASCADE,"lineNo" INTEGER NOT NULL,"rawText" TEXT NOT NULL,"parsedName" TEXT,"qty" INTEGER,"setCode" TEXT,"collectorNo" TEXT,"reason" TEXT,"state" "ImportLineState" NOT NULL DEFAULT 'unresolved',"resolvedScryfallId" UUID,CONSTRAINT "ImportLine_qty_check" CHECK ("qty" IS NULL OR "qty" BETWEEN 1 AND 9999),UNIQUE("batchId","lineNo"));
CREATE TABLE "MutationReceipt" ("id" UUID PRIMARY KEY,"memberId" UUID NOT NULL REFERENCES "Member"("id") ON DELETE CASCADE,"requestId" UUID NOT NULL,"payloadHash" VARCHAR(64) NOT NULL,"response" JSONB NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("memberId","requestId"));
